-- Versioned initial PostgreSQL schema for Neon. Idempotent for existing installs.
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS authors(id BIGSERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '', social TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS articles(id BIGSERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, deck TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL, author_id BIGINT REFERENCES authors(id) ON DELETE SET NULL, image TEXT NOT NULL DEFAULT '', image_caption TEXT NOT NULL DEFAULT '', image_alt TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), featured INTEGER NOT NULL DEFAULT 0, breaking INTEGER NOT NULL DEFAULT 0, video_id BIGINT, published_at TEXT, updated_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS article_authors(article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, author_id BIGINT NOT NULL REFERENCES authors(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(article_id,author_id));
CREATE TABLE IF NOT EXISTS videos(id BIGSERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL, author_id BIGINT REFERENCES authors(id) ON DELETE SET NULL, url TEXT NOT NULL DEFAULT '', thumbnail TEXT NOT NULL DEFAULT '', duration TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscribers(id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, subscribed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
